/**
 * Get the A2A agent card
 *
 * The A2A 1.0 agent card of this environment: a pi-kit coding agent that takes room tasks over JSON-RPC with push notifications.
 */
export const a2aCard = <ThrowOnError extends boolean = false>(options?: Options<A2aCardData, ThrowOnError>): RequestResult<A2aCardResponses, A2aCardErrors, ThrowOnError> => (options?.client ?? client).get<A2aCardResponses, A2aCardErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/a2a/.well-known/agent-card.json',
    ...options
});

/**
 * Call the A2A agent
 *
 * The A2A 1.0 JSON-RPC endpoint, served by the A2A JavaScript SDK. SendMessage starts a room task (with the room-task extension, declared in A2A-Extensions) or answers its questions; GetTask, ListTasks and CancelTask work on the caller’s tasks. SendStreamingMessage and SubscribeToTask answer with Server-Sent Events, one JSON-RPC response per event, until the task ends or stops for input. Progress and results also go to the push notification URL given with the task.
 */
export const a2aRpc = <ThrowOnError extends boolean = false>(options: Options<A2aRpcData, ThrowOnError, A2aRpcResponse>): Promise<ServerSentEventsResult<A2aRpcResponses>> => (options.client ?? client).sse.post<A2aRpcResponses, A2aRpcErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/a2a',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Get the A2A agent card at the well-known address
 *
 * The A2A 1.0 agent card at the address A2A clients look for, outside /api. It names two JSON-RPC interfaces: this server’s /api/a2a, which needs the pi-kit token as a bearer token, and the pi-kit-peer interface paired pi-kits use. Asks for the token like every other route.
 */
export const a2aWellKnownCard = <ThrowOnError extends boolean = false>(options?: Options<A2aWellKnownCardData, ThrowOnError>): RequestResult<A2aWellKnownCardResponses, A2aWellKnownCardErrors, ThrowOnError> => (options?.client ?? client).get<A2aWellKnownCardResponses, A2aWellKnownCardErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/.well-known/agent-card.json',
    ...options
});
